auto provider = pact_consumer::Pact("TodoAppCpp", "TodoServiceCpp");
provider.given("i have a list of projects")
    .uponReceiving("a request for projects")
    .withRequest("GET", "/projects")
    .willRespondWith(200)
    .withResponseJsonBody(Object({
        { "projects", EachLike(Object({ { "id", Integer(3) },
                                        { "name", Like("Project 1") } })) }}));

provider.run_test([](const std::string &mockUrl) {   // mock server + validation
    TodoClient client(mockUrl);                       // the code under test
    assert(client.projects().size() == 1);
});
